import React, { useState, useEffect } from 'react';
import { api } from '../api';

export default function Settings() {
  const [key, setKey] = useState('');
  const [saved, setSaved] = useState(false);
  const [testing, setTesting] = useState(false);
  const [testResult, setTestResult] = useState('');
  const [show, setShow] = useState(false);

  useEffect(() => {
    // Load masked key status from backend
    api.get('/settings/apikey-status').then(r => {
      if (r.data.configured) setSaved(true);
    }).catch(() => {});
  }, []);

  const handleSave = async () => {
    if (!key.trim()) return;
    try {
      await api.post('/settings/apikey', { api_key: key.trim() });
      setSaved(true);
      setKey('');
      setTestResult('');
      alert('API key saved successfully.');
    } catch (e) {
      alert('Failed to save: ' + (e.response?.data?.detail || e.message));
    }
  };

  const handleTest = async () => {
    setTesting(true);
    setTestResult('');
    try {
      const r = await api.post('/query', { query: 'show all students' });
      setTestResult('✅ AI query working — OpenAI key is valid.');
    } catch (e) {
      const msg = e.response?.data?.detail || e.message;
      if (msg.includes('OPENAI_API_KEY') || msg.includes('api_key') || msg.includes('401')) {
        setTestResult('❌ Invalid or missing API key.');
      } else {
        setTestResult('✅ Backend reachable (query ran, check results).');
      }
    } finally {
      setTesting(false);
    }
  };

  const handleClear = async () => {
    if (!window.confirm('Remove the saved API key?')) return;
    await api.delete('/settings/apikey').catch(() => {});
    setSaved(false);
    setTestResult('');
  };

  return (
    <div>
      <div className="card">
        <h2>🔑 OpenAI API Key</h2>
        <p style={{ color: '#555', marginBottom: 16, fontSize: '0.9rem', lineHeight: 1.6 }}>
          The AI Query feature requires an OpenAI API key. Your key is stored only in the backend
          process memory and never sent to the frontend.
          <br />
          Get your key at{' '}
          <a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer"
            style={{ color: '#1a73e8' }}>
            platform.openai.com/api-keys
          </a>
        </p>

        {saved && (
          <div className="alert alert-success" style={{ marginBottom: 16 }}>
            ✅ API key is configured. You can update it by entering a new one below.
          </div>
        )}

        <div style={{ display: 'flex', gap: 10, marginBottom: 12, alignItems: 'center' }}>
          <input
            type={show ? 'text' : 'password'}
            className="search-input"
            placeholder="sk-proj-..."
            value={key}
            onChange={e => setKey(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSave()}
            style={{ fontFamily: 'monospace', flex: 1 }}
          />
          <button className="btn btn-outline" onClick={() => setShow(s => !s)} title="Toggle visibility">
            {show ? '🙈' : '👁️'}
          </button>
          <button className="btn btn-primary" onClick={handleSave} disabled={!key.trim()}>
            💾 Save Key
          </button>
          {saved && (
            <button className="btn btn-danger" onClick={handleClear}>🗑️ Remove</button>
          )}
        </div>

        <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
          <button className="btn btn-outline" onClick={handleTest} disabled={testing}>
            {testing ? <><span className="spinner" /> Testing...</> : '🧪 Test Connection'}
          </button>
          {testResult && (
            <span className={`alert ${testResult.startsWith('✅') ? 'alert-success' : 'alert-error'}`}
              style={{ margin: 0, padding: '6px 12px' }}>
              {testResult}
            </span>
          )}
        </div>
      </div>

      <div className="card">
        <h2>ℹ️ How to get an OpenAI API Key</h2>
        <ol style={{ paddingLeft: 20, lineHeight: 2.2, color: '#555', fontSize: '0.9rem' }}>
          <li>Go to <a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer" style={{ color: '#1a73e8' }}>platform.openai.com/api-keys</a></li>
          <li>Sign in or create a free account</li>
          <li>Click <strong>"Create new secret key"</strong></li>
          <li>Copy the key (starts with <code>sk-</code>)</li>
          <li>Paste it in the field above and click <strong>Save Key</strong></li>
          <li>Click <strong>Test Connection</strong> to verify it works</li>
        </ol>
        <div className="alert alert-warn" style={{ marginTop: 12 }}>
          ⚠️ Free tier has rate limits. For heavy use, add billing at platform.openai.com/billing
        </div>
      </div>
    </div>
  );
}
